<template><div class="page"><AppNav/><main class="content"><header class="title"><div><span class="eyebrow">CAMPUS LEARNING COMMUNITY</span><h1>校园学习论坛 <small v-if="me.is_admin" class="admin-badge">管理员模式</small></h1><p>向同学和老师提问、分享资料与复习方法。请勿发布个人隐私或未授权课程材料。</p></div><button class="primary" @click="dialog=true">＋ 发布交流帖</button></header><section class="categories"><button v-for="item in ['全部','学习交流','课程答疑','资料分享','项目协作']" :key="item" :class="{active:category===item}" @click="category=item">{{item}}</button></section><section class="posts"><article v-for="post in filtered" :key="post.id" class="post" @click="comments(post)"><div class="avatar">{{post.author_name?.slice(0,1)}}</div><div class="post-main"><span>{{post.category}} · {{post.author_name}}</span><h2>{{post.title}}</h2><p>{{post.content}}</p><small>◌ {{post.comment_count}} 条讨论</small></div><button v-if="canDelete(post.author_id)" class="delete" @click.stop="removePost(post)">删除</button><span class="arrow">→</span></article><div v-if="!filtered.length" class="empty">这个分区还没有帖子，来分享第一个学习话题吧。</div></section></main><el-dialog v-model="dialog" title="发布交流帖" width="520px"><el-form label-position="top"><el-form-item label="分区"><el-select v-model="form.category" style="width:100%"><el-option v-for="item in ['学习交流','课程答疑','资料分享','项目协作']" :key="item" :label="item" :value="item"/></el-select></el-form-item><el-form-item label="标题"><el-input v-model="form.title" maxlength="60" show-word-limit/></el-form-item><el-form-item label="正文"><el-input v-model="form.content" type="textarea" :rows="6"/></el-form-item></el-form><template #footer><button class="primary" @click="publish">发布</button></template></el-dialog><el-dialog v-model="commentDialog" :title="activePost?.title" width="600px"><p class="post-text">{{activePost?.content}}</p><div v-for="comment in commentList" :key="comment.id" class="comment"><div class="comment-head"><b>{{comment.author_name}}</b><button v-if="canDelete(comment.author_id)" class="delete" @click="removeComment(comment)">删除</button></div><p>{{comment.content}}</p></div><el-input v-model="commentInput" placeholder="发表你的学习想法" @keyup.enter="sendComment"><template #append><button class="plain" @click="sendComment">发送</button></template></el-input></el-dialog></div></template>
<script setup>import{computed,onMounted,ref}from'vue';import{ElMessage}from'element-plus';import AppNav from'../components/AppNav.vue';import{api,post}from'../utils/api';const posts=ref([]),category=ref('全部'),dialog=ref(false),commentDialog=ref(false),activePost=ref(null),commentList=ref([]),commentInput=ref(''),form=ref({category:'学习交流',title:'',content:''}),me=JSON.parse(localStorage.getItem('user')||'{}');const filtered=computed(()=>category.value==='全部'?posts.value:posts.value.filter(p=>p.category===category.value));const canDelete=authorId=>Number(authorId)===Number(me.id)||me.is_admin;async function load(){posts.value=await api('/forum/posts')}async function publish(){try{await post('/forum/posts',form.value);dialog.value=false;form.value={category:'学习交流',title:'',content:''};load()}catch(e){ElMessage.error(e.message)}}async function comments(post){activePost.value=post;commentList.value=await api(`/forum/posts/${post.id}/comments`);commentDialog.value=true}async function sendComment(){if(!commentInput.value.trim())return;await post(`/forum/posts/${activePost.value.id}/comments`,{content:commentInput.value});commentInput.value='';comments(activePost.value);load()}async function removePost(post){if(!confirm(`确定删除“${post.title}”及其全部评论吗？`))return;try{await api(`/forum/posts/${post.id}`,{method:'DELETE'});if(activePost.value?.id===post.id)commentDialog.value=false;await load();ElMessage.success('帖子已删除')}catch(e){ElMessage.error(e.message)}}async function removeComment(comment){if(!confirm('确定删除这条评论吗？'))return;try{await api(`/forum/comments/${comment.id}`,{method:'DELETE'});await comments(activePost.value);await load();ElMessage.success('评论已删除')}catch(e){ElMessage.error(e.message)}}onMounted(()=>load().catch(e=>ElMessage.error(e.message)))</script>
<style scoped>.content{max-width:980px;margin:auto;padding:36px 5vw}.title{display:flex;justify-content:space-between;align-items:end;gap:20px}.eyebrow{font-size:11px;color:#b26b4a;letter-spacing:1.3px;font-weight:800}.title h1{color:#623a2b;margin:5px 0;font-size:31px}.admin-badge{vertical-align:middle;background:#6c4c90;color:#fff;border-radius:11px;padding:5px 8px;font-size:11px}.title p{color:#92776a;max-width:670px;line-height:1.6}.primary{border:0;border-radius:13px;background:#c96d42;color:white;padding:11px 15px;font-weight:700;cursor:pointer;white-space:nowrap}.categories{display:flex;gap:8px;margin:26px 0;overflow:auto}.categories button{border:1px solid #edddd1;background:#fffdfa;color:#936f5e;border-radius:18px;padding:8px 13px;white-space:nowrap;cursor:pointer}.categories .active{background:#fff0e4;color:#aa552f;border-color:#eac0aa}.posts{display:grid;gap:12px}.post,.empty{background:#fffdfa;border:1px solid #f1e2d8;border-radius:20px;box-shadow:0 10px 30px #9f4c2b0d}.post{padding:18px;display:flex;gap:13px;align-items:start;cursor:pointer}.post:hover{transform:translateY(-1px);border-color:#e8c8b6}.avatar{width:38px;height:38px;display:grid;place-items:center;border-radius:13px;background:#f8dfce;color:#a95431;font-weight:800}.post-main{flex:1;min-width:0}.post-main span,.post-main small{font-size:12px;color:#a18070}.post-main h2{font-size:18px;color:#684231;margin:5px 0}.post-main p{color:#866c5e;margin:0 0 7px;line-height:1.55;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}.arrow{color:#bc6944;font-size:21px}.delete{border:0;background:#fff0ed;color:#ba5541;border-radius:9px;padding:6px 9px;font-size:12px;cursor:pointer}.empty{padding:35px;text-align:center;color:#9c8173}.post-text{color:#785d4e;line-height:1.65}.comment{padding:11px 0;border-top:1px solid #f2e5dd}.comment-head{display:flex;justify-content:space-between;align-items:center}.comment b{font-size:13px;color:#a15738}.comment p{color:#785f52;margin:5px 0}.plain{border:0;background:transparent;color:#af5c3a;cursor:pointer}@media(max-width:640px){.content{padding:20px}.title{align-items:start;flex-direction:column}.title h1{font-size:26px}}</style>
